//! Port of `src/synthetic/Bytes.zig`.
//!
//! STATUS: ported
//!
//! Generates bytes.

use std::io;

use super::generator::{self, Generator, Writer};
use super::Random;

/// Generates bytes.
#[derive(Debug, Clone)]
pub struct Bytes {
    /// Random number generator.
    pub rand: Random,

    /// The minimum and maximum length of the generated bytes.
    pub min_len: usize,
    pub max_len: usize,

    /// The possible bytes that can be generated. If a byte is duplicated
    /// in the alphabet, it will be more likely to be generated. That's a
    /// side effect of the generator, not an intended use case.
    pub alphabet: Option<&'static [u8]>,
}

/// Generate an alphabet given a function that returns true/false for a
/// given byte.
///
/// Zig computes this at comptime; Rust callers store the result in a
/// `LazyLock` (see [`alphabet!`](crate::synthetic::bytes::alphabet)).
pub fn generate_alphabet(func: fn(u8) -> bool) -> Vec<u8> {
    (0..=255u8).filter(|&c| func(c)).collect()
}

/// Declare a lazily generated `&'static [u8]` alphabet (the Rust form of
/// `pub const x = Bytes.generateAlphabet(func);`).
macro_rules! alphabet {
    ($(#[$meta:meta])* $vis:vis static $name:ident = $func:expr;) => {
        $(#[$meta])*
        $vis static $name: ::std::sync::LazyLock<&'static [u8]> =
            ::std::sync::LazyLock::new(|| {
                ::std::boxed::Box::leak(
                    $crate::synthetic::bytes::generate_alphabet($func).into_boxed_slice(),
                )
            });
    };
}
pub(crate) use alphabet;

impl Bytes {
    /// A new generator with the Zig default field values.
    pub fn init(rand: Random) -> Bytes {
        Bytes {
            rand,
            min_len: 1,
            max_len: usize::MAX,
            alphabet: None,
        }
    }

    pub fn generator(&mut self) -> &mut dyn Generator {
        self
    }

    /// Return a copy of the Bytes, but with a new alphabet.
    pub fn new_alphabet(&self, new_alphabet: Option<&'static [u8]>) -> Bytes {
        Bytes {
            rand: self.rand.clone(),
            alphabet: new_alphabet,
            min_len: self.min_len,
            max_len: self.max_len,
        }
    }

    /// Return a copy of the Bytes, but with a new min_len. The new min
    /// len cannot be more than the previous max_len.
    pub fn at_least(&self, new_min_len: usize) -> Bytes {
        Bytes {
            rand: self.rand.clone(),
            alphabet: self.alphabet,
            min_len: self.max_len.min(new_min_len),
            max_len: self.max_len,
        }
    }

    /// Return a copy of the Bytes, but with a new max_len. The new max_len cannot
    /// be more the previous max_len.
    pub fn at_most(&self, new_max_len: usize) -> Bytes {
        Bytes {
            rand: self.rand.clone(),
            alphabet: self.alphabet,
            min_len: self.min_len.min(self.max_len.min(new_max_len)),
            max_len: self.max_len.min(new_max_len),
        }
    }

    pub fn next(&self, writer: &mut Writer<'_>, max_len: usize) -> io::Result<()> {
        let _ = self.at_most(max_len).write(writer)?;
        Ok(())
    }

    /// Zig `format` (used with `{f}`): write random data to the writer.
    pub fn format(&self, writer: &mut Writer<'_>) -> io::Result<()> {
        let _ = self.write(writer)?;
        Ok(())
    }

    /// Write some random data and return the number of bytes written.
    pub fn write(&self, writer: &mut Writer<'_>) -> io::Result<usize> {
        debug_assert!(self.min_len >= 1);
        debug_assert!(self.max_len >= self.min_len);

        let len = self
            .rand
            .int_range_at_most_biased::<64>(self.min_len as u64, self.max_len as u64)
            as usize;

        let mut buf = [0u8; 8];

        let mut remaining = len;
        while remaining > 0 {
            let data = &mut buf[..remaining.min(8)];
            self.rand.bytes(data);
            if let Some(alphabet) = self.alphabet {
                for byte in data.iter_mut() {
                    *byte = alphabet[*byte as usize % alphabet.len()];
                }
            }
            writer.write_all(data)?;
            remaining -= data.len();
        }

        Ok(len)
    }
}

impl Generator for Bytes {
    fn next(&mut self, writer: &mut Writer<'_>, max_len: usize) -> Result<(), generator::Error> {
        Bytes::next(self, writer, max_len).map_err(generator::Error::from)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::synthetic::{DefaultPrng, FixedWriter};

    #[test]
    fn bytes() {
        let prng = DefaultPrng::init(0);
        let mut buf = [0u8; 256];
        let len = buf.len();
        let mut writer = FixedWriter::fixed(&mut buf);
        let mut v = Bytes {
            min_len: len,
            max_len: len,
            ..Bytes::init(prng.random())
        };
        let gen = v.generator();
        gen.next(&mut writer, len).unwrap();
        assert_eq!(len, writer.buffered().len());
    }
}
